import { CommonModule } from '@angular/common';
import {
  ChangeDetectorRef,
  Component,
  EventEmitter,
  Inject,
  Input,
  OnChanges,
  OnInit,
  Optional,
  Output,
  SimpleChanges,
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import { AvatarComponent } from '../../avatar/avatar.component';
import { MatSlideToggleModule } from '@angular/material/slide-toggle';
import { IconComponent } from '../../icon/icon.component';
import { MyfileService } from '../../../services/myfile/myfile.service';
import { MAT_DIALOG_DATA, MatDialog } from '@angular/material/dialog';
import { SecureStorageService } from '../../../../core/services/storage/secure-storage.service';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatTooltipModule } from '@angular/material/tooltip';
import { ButtonComponent } from '../../button/button.component';
import { MYFILES_TOOL_EVENTS } from '../../../interfaces/myfiles-tool-events.interface';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'share-with-team',
  standalone: true,
  imports: [CommonModule, FormsModule, AvatarComponent, MatSlideToggleModule, IconComponent, MatCheckboxModule, MatTooltipModule, ButtonComponent, TranslateModule],
  templateUrl: './sharewithteam.component.html',
  styleUrl: './sharewithteam.component.scss'
})
export class SharewithteamComponent implements OnInit, OnChanges {
  @Input() activeuser: boolean = false;
  @Input() globalshare: boolean = false;
  @Input() bottomshr: boolean = false;
  @Input() nCaseid: string;
  @Input() nBundleid: string;
  @Input() nBundledetailid: string;
  @Input() isUpdate: boolean;
  teamlist = [];
  users = [];
  userDetail: any = {}
  // nTeamid: string;
  @Input() nSectionid: string;
  @Output() checkevent = new EventEmitter<any>();
  @Output() shareEvent = new EventEmitter<any>();
  bIsannotation: boolean = true;
  bIsalert: boolean = true;
  showshare: boolean = false;
  nTeamid: number = 0;
  checkUserlength = 0;
  checkedUsers = [];
  shareids = []
  constructor(
    private readonly myfileS: MyfileService,
    @Optional() @Inject(MAT_DIALOG_DATA) public data: any,
    private readonly dialog: MatDialog,
    private readonly ss: SecureStorageService,
    private readonly cdr: ChangeDetectorRef,
  ) {
    if (data) {
      this.nCaseid = data['nCaseid'];
      this.nBundleid = data['nBundleid'];
      this.nBundledetailid = data['nBundledetailid'];
      this.nSectionid = data['nSectionid'];
      this.shareids = data['ids'];
    }
  }

  ngOnInit(): void {
    void this.init();
  }

  private async init(): Promise<void> {
    this.userDetail = await this.ss.getUserInfo();
    await this.getTeamList();
    this.showshare = !!this.globalshare;
    this.cdr.detectChanges();
  }
  ngOnChanges(_changes: SimpleChanges): void {
    void this.getUserlist();
    this.cdr.detectChanges();
  }

  async getTeamList(): Promise<void> {
    const res = await this.myfileS.teamuserList(this.nCaseid);
    this.teamlist = res;
    for (let team of this.teamlist) {
      if (team.users.length && team.users.some(e => e.nUserid == this.userDetail.nUserid)) {
        this.nTeamid = team.nTeamid;
        break;
      }
    }
    this.teamlist = this.teamlist.filter(team => this.nTeamid === team.nTeamid);
    void this.getUserlist();
    this.cdr.detectChanges();
  }

  async getUserlist(): Promise<void> {
    const res = await this.myfileS.getshareduserby_bundleid(this.nSectionid, this.nBundleid, this.nBundledetailid ? this.nBundledetailid : null);
    const firstRow = (res as any)?.[0];
    this.users = firstRow?.jUsers ?? firstRow?.users ?? [];
    this.checkevent.emit(0);
    if (!this.users?.length) {
      this.checkUserlength = 0;
      this.checkedUsers = [];
      this.cdr.detectChanges();
      return
    }

    const userIdSet = new Set(this.users);

    // Process each team and user more efficiently

    this.teamlist = this.teamlist.map(team => {
      const updateUsers = team.users.map(user => ({
        ...user,
        isCheck: userIdSet.has(user.nUserid)  // Set isCheck based on absence in userIdSet
      }));

      // Check if all users in the team are checked
      const isAllUsersChecked = updateUsers.filter(a => a.nUserid != this.userDetail.nUserid).every(user => user.isCheck);
      this.checkUserlength = updateUsers.filter(e => e.isCheck).length;
      this.checkevent.emit(this.checkUserlength);
      this.checkedUsers = updateUsers.filter(e => e.isCheck);
      this.cdr.detectChanges();
      return {
        ...team,
        users: updateUsers,
        isCheck: isAllUsersChecked  // Set the team's check status based on all users' check status
      };
    });
    this.cdr.detectChanges();
  }

  checkall(x) {
    x.users
      .filter(a => a.nUserid != this.userDetail.nUserid)
      .forEach(a => {
        a.isCheck = x.isCheck;
      });
  }

  checkList() {
    if (!this.teamlist?.length) {
      return;
    }

    if (this.teamlist[0].users.some(a => a.nUserid != this.userDetail.nUserid && !a.isCheck)) {
      this.teamlist[0].isCheck = false;
    } else {
      this.teamlist[0].isCheck = true;
    };
  }

  async shareWithuser() {
    let userids: string[] = []
    for (let team of this.teamlist) {
      let ids = team.users.filter(e => e.isCheck).map(e => e.nUserid);
      userids = [...userids, ...ids]
      // jUserid: mn.nUserid ? mn.nUserid : 0
    }
    const mdl = {
      nSectionid: this.nSectionid, nBundleid: this.nBundleid, nBundledetailid: this.nBundledetailid, jUsers: userids,
      bIsannotation: this.bIsannotation, bIsalert: this.bIsalert, jShareids: this.shareids
    }
    let res = await this.myfileS.sharedFileData(mdl);
    if (res) {
      this.dialog.closeAll();
    }
  }

  close() {
    this.dialog.closeAll();
  }

  toggleShareToAll(tm) {
    const allChecked = tm.users.every((user) => user.isCheck);
    tm.users.forEach((user) => (user.isCheck = !allChecked));
  }

  // Check if all users are selected
  isShareToAllActive(tm): boolean {
    return tm.users.every((user) => user.isCheck);
  }

  iconclick() {
    this.shareEvent.emit({ event: MYFILES_TOOL_EVENTS.ICON_CLICK, nBundleid: this.nBundleid, data: this.nBundledetailid })
  }

  share() {
    if (this.checkedUsers.length) {
      this.showshare = !this.showshare;
    }
    else {
      this.shareEvent.emit({ event: MYFILES_TOOL_EVENTS.ICON_CLICK, nBundleid: this.nBundleid, data: this.nBundledetailid })
    }
  }
}
